@startuml
class Employee {
  +identifyingNumber : int
  +name : string
  +address : string
}

class PartAccessory {
  +category : string
  +serialNumber : string
  +price : double
}

class Car {
  +licensePlate : string
  +make : string
  +model : string
  +color : string
}

class Owner {
  +name : string
  +identifyingNumber : string
  +address : string
  +phone : string
}

class AssemblyService {
  +kms : int
  +workHours : float
  +admissionDate : date
  +finishDate : date
}

class CarModelFit {
}

Employee "1" -- "*" AssemblyService : responsible for
AssemblyService "1" -- "1" Car : executed in
AssemblyService "*" -- "*" PartAccessory : fitted with
PartAccessory "*" -- "*" CarModelFit : fits
CarModelFit "*" -- "1" Car : model of
Car "1" -- "1" Owner : owned by
Owner "1" -- "*" Car : owns
@enduml

